import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.CWWEQfK7.js";const u=JSON.parse('{"title":"Backend configuration: values to change first","description":"Start from the deployment example and configure data services, application secrets, browser access, and repository boundaries.","frontmatter":{"page_id":"configuration-basic","title":"Backend configuration: values to change first","description":"Start from the deployment example and configure data services, application secrets, browser access, and repository boundaries."},"headers":[],"relativePath":"en/configuration/basic.md","filePath":"en/configuration/basic.md","lastUpdated":1786627803000}'),n={name:"en/configuration/basic.md"};function r(o,e,d,l,c,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="backend-configuration-values-to-change-first" tabindex="-1">Backend configuration: values to change first <a class="header-anchor" href="#backend-configuration-values-to-change-first" aria-label="Permalink to &quot;Backend configuration: values to change first&quot;">​</a></h1><p>The quick deployment stores backend settings in <code>/etc/ershu/.env</code>. API, Worker, MCP, and database commands read it from that directory. The installer creates the file from <code>.env.example</code> in the deployment archive. Do not reconstruct it from the environment reference.</p><p>When running from source, copy <code>.env.example</code> to <code>.env</code> in the project working directory instead.</p><p>This page covers the values that matter during the first setup. See the <a href="./environment-reference">environment reference</a> for every field, type, and default.</p><h2 id="_1-point-the-processes-at-three-data-services" tabindex="-1">1. Point the processes at three data services <a class="header-anchor" href="#_1-point-the-processes-at-three-data-services" aria-label="Permalink to &quot;1. Point the processes at three data services&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Service</th><th>Main use</th><th>Settings</th></tr></thead><tbody><tr><td>PostgreSQL</td><td>Users, projects, permissions, runs, documents, and system settings</td><td><code>DATABASE_URL</code> and pool settings</td></tr><tr><td>Redis</td><td>Login throttling and scheduled-poller lease coordination</td><td><code>REDIS_URL</code></td></tr><tr><td>Milvus</td><td>Vector indexes and semantic retrieval</td><td><code>MILVUS_URI</code>, <code>MILVUS_TOKEN</code>, <code>MILVUS_DB_NAME</code></td></tr></tbody></table><p>API, Worker, and MCP must use the same PostgreSQL database. When vector retrieval is enabled, they should also use the same Milvus database. Redis does not hold the Worker&#39;s durable task queue.</p><p>With the single-host Compose file, the default addresses already point to the local machine. Copy the PostgreSQL password from <code>/etc/ershu/compose.env</code> into <code>DATABASE_URL</code> in <code>/etc/ershu/.env</code>.</p><h2 id="_2-generate-four-long-lived-secrets" tabindex="-1">2. Generate four long-lived secrets <a class="header-anchor" href="#_2-generate-four-long-lived-secrets" aria-label="Permalink to &quot;2. Generate four long-lived secrets&quot;">​</a></h2><p>The deployment helper generates PostgreSQL and MinIO passwords, <code>DATABASE_URL</code>, and four long-lived secrets:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/ershu/current</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  scripts/generate_config_values.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Put <code>SECRET_KEY</code>, <code>ENCRYPTION_KEY</code>, and <code>MCP_KEY_PEPPER</code> in <code>/etc/ershu/.env</code>:</p><ul><li><code>SECRET_KEY</code> protects login and CSRF tokens.</li><li><code>ENCRYPTION_KEY</code> encrypts stored repository credentials and model keys.</li><li><code>MCP_KEY_PEPPER</code> protects MCP key digests.</li></ul><p>Each value must contain at least 32 characters. They must be different and cannot remain placeholders such as <code>replace-me</code>. Changing them invalidates existing sessions, encrypted values, or MCP keys, so keep production values in a secret manager.</p><p>The same command prints <code>OPAQUE_SERVER_SETUP</code>. Put it in the same file. Changing it makes existing password records unusable. Production requires an explicit value, so keep the first deployment&#39;s value.</p><h2 id="_3-configure-browsers-and-the-reverse-proxy" tabindex="-1">3. Configure browsers and the reverse proxy <a class="header-anchor" href="#_3-configure-browsers-and-the-reverse-proxy" aria-label="Permalink to &quot;3. Configure browsers and the reverse proxy&quot;">​</a></h2><p>Local development can keep:</p><div class="language-dotenv vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">8000</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">CORS_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:3000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SECURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">false</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SAMESITE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>For production:</p><ul><li>set <code>ENVIRONMENT=production</code>;</li><li>set <code>SESSION_COOKIE_SECURE=true</code>;</li><li>list only the real HTTPS frontend origin in <code>CORS_ORIGINS</code>;</li><li>enable <code>PROXY_HEADERS</code> behind a reverse proxy and restrict <code>FORWARDED_ALLOW_IPS</code> to real proxy addresses;</li><li>keep API and MCP on loopback or a private network and expose only the HTTPS proxy.</li></ul><p>Serving the browser app and API from one domain is the simplest layout. A cross-origin setup has to align CORS, cookies, origin checks, and the forwarded scheme, not just the frontend URL.</p><h2 id="_4-restrict-repository-sources" tabindex="-1">4. Restrict repository sources <a class="header-anchor" href="#_4-restrict-repository-sources" aria-label="Permalink to &quot;4. Restrict repository sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Recommendation</th></tr></thead><tbody><tr><td><code>REPOSITORY_STORAGE_PATH</code></td><td>Use an explicit, writable, persistent directory</td></tr><tr><td><code>GIT_ALLOWED_HOSTS</code></td><td>List only Git hosts the team actually uses</td></tr><tr><td><code>ALLOW_INSECURE_GIT_URLS</code></td><td>Keep <code>false</code></td></tr><tr><td><code>ALLOW_FILE_GIT_URLS</code></td><td>Keep <code>false</code> unless local file URLs have been reviewed</td></tr><tr><td><code>TRUSTED_LOCAL_PATHS</code></td><td>List only local repository roots Ershu may read</td></tr><tr><td><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code></td><td>Keep <code>false</code> in production</td></tr></tbody></table><p>A local path visible to the browser machine may not be visible to the Worker or MCP host. Before registering a local repository, confirm that the actual processes can read the same path.</p><p>GitHub and GitLab tokens can serve as fallback credentials, but repository-specific tokens or SSH keys in the web vault are usually easier to control. Never place real credentials in <code>.env.example</code>.</p><h2 id="_5-keep-model-channels-out-of-env" tabindex="-1">5. Keep model channels out of <code>.env</code> <a class="header-anchor" href="#_5-keep-model-channels-out-of-env" aria-label="Permalink to &quot;5. Keep model channels out of \`.env\`&quot;">​</a></h2><p>Create language-model, embedding, and reranker channels in administration. Model names, API keys, endpoints, and pricing settings are stored in the database, with sensitive values encrypted by <code>ENCRYPTION_KEY</code>.</p><p>Wiki generation needs at least one working language-model channel. Semantic search also needs a separate embedding channel. Keyword search still works without an embedding model.</p><h2 id="_6-verify-the-effective-setup" tabindex="-1">6. Verify the effective setup <a class="header-anchor" href="#_6-verify-the-effective-setup" aria-label="Permalink to &quot;6. Verify the effective setup&quot;">​</a></h2><p>The quick deployment uses systemd to apply migrations and start the backend:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-migrate.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu.target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>Check:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/api/v1/health/dependencies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>The first endpoint only shows that API can respond. The second checks PostgreSQL and Milvus, but not Redis, Worker, or model channels. A complete deployment also needs a Worker that can claim a real run, a successful sign-in, and a tested model channel.</p><p>For source installations, use the UV commands in the <a href="/en/development/local-setup">local development setup</a>.</p><p>If you do not know which setting won, read <a href="./loading-and-overrides">loading and overrides</a>. Before launch, work through <a href="./security">permissions and security</a>.</p>`,36)])])}const k=s(n,[["render",r]]);export{u as __pageData,k as default};
